import { generateGeminiAssistantReply } from "./provider";

/**
 * Validates if the provided AI output contains fabricated facts
 * not present in the given context.
 * 
 * @param context The factual context provided to the model
 * @param output The output generated by the model
 * @returns {Promise<{ isHallucinated: boolean; reasoning: string }>}
 */
export async function checkHallucination(context: string, output: string): Promise<{ isHallucinated: boolean; reasoning: string }> {
  try {
    const prompt = `
You are an expert fact-checker and hallucination detector. 
Compare the GENERATED OUTPUT against the provided SOURCE CONTEXT.

SOURCE CONTEXT:
"""
${context}
"""

GENERATED OUTPUT:
"""
${output}
"""

Task: Determine if the GENERATED OUTPUT contains any factual claims, metrics, names, or events that are NOT explicitly supported by or reasonably inferred from the SOURCE CONTEXT. 
Respond ONLY with a JSON object in this exact format:
{
  "isHallucinated": boolean,
  "reasoning": "brief explanation"
}
`;

    const responseText = await generateGeminiAssistantReply([{ role: "user", text: prompt }]);
    const cleanJson = responseText.replace(/^```json\s*/i, "").replace(/^```\s*/i, "").replace(/```\s*$/i, "").trim();
    const parsed = JSON.parse(cleanJson);
    
    return {
      isHallucinated: Boolean(parsed.isHallucinated),
      reasoning: String(parsed.reasoning)
    };
  } catch (error) {
    console.error("Error in checkHallucination:", error);
    // Fail open if the checker itself fails
    return { isHallucinated: false, reasoning: "Checker failed to execute" };
  }
}

/**
 * Validates if the text contains biased or exclusionary language based on protected attributes.
 * 
 * @param text The text to evaluate
 * @param contextType The type of text (e.g., 'job_description', 'screening_evaluation')
 * @returns {Promise<{ isBiased: boolean; reasoning: string; suggestedEdits?: string[] }>}
 */
export async function checkBias(text: string, contextType: "job_description" | "screening_evaluation"): Promise<{ isBiased: boolean; reasoning: string; suggestedEdits?: string[] }> {
  try {
    const prompt = `
You are an expert in Diversity, Equity, and Inclusion (DEI) and responsible AI.
Review the following ${contextType} for any biased, exclusionary, or discriminatory language related to protected attributes (gender, age, race, religion, disability, etc.) or unnecessarily restrictive requirements that could deter diverse candidates.

TEXT TO REVIEW:
"""
${text}
"""

Task: Determine if the text contains bias. If it does, provide a reasoning and suggest alternative phrasing.
Respond ONLY with a JSON object in this exact format:
{
  "isBiased": boolean,
  "reasoning": "brief explanation of the bias found, or why it is neutral",
  "suggestedEdits": ["optional array of suggested replacements"]
}
`;

    const responseText = await generateGeminiAssistantReply([{ role: "user", text: prompt }]);
    const cleanJson = responseText.replace(/^```json\s*/i, "").replace(/^```\s*/i, "").replace(/```\s*$/i, "").trim();
    const parsed = JSON.parse(cleanJson);
    
    return {
      isBiased: Boolean(parsed.isBiased),
      reasoning: String(parsed.reasoning),
      suggestedEdits: Array.isArray(parsed.suggestedEdits) ? parsed.suggestedEdits.map(String) : undefined
    };
  } catch (error) {
    console.error("Error in checkBias:", error);
    // Fail open if the checker itself fails
    return { isBiased: false, reasoning: "Checker failed to execute" };
  }
}
